    if user is None:
        raise ValueError("User not found")

    # ---------- basic argument validation ----------
    if cabin not in ("basic_economy", "economy", "business"):
        raise ValueError("Invalid cabin: " + str(cabin))
    if flight_type not in ("one_way", "round_trip"):
        raise ValueError("Invalid flight type: " + str(flight_type))
    if insurance not in ("yes", "no"):
        raise ValueError("Invalid insurance value: " + str(insurance))
    if not isinstance(passengers, list) or len(passengers) == 0:
        raise ValueError("At least one passenger is required")
    if len(passengers) > 5:
        raise ValueError("Each reservation can have at most five passengers")
    for p in passengers:
        if not isinstance(p, dict):
            raise ValueError("Invalid passenger entry")
        for key in ("first_name", "last_name", "date_of_birth"):
            if not p.get(key):
                raise ValueError("Each passenger needs first_name, last_name and date_of_birth")
    if not isinstance(flights, list) or len(flights) == 0:
        raise ValueError("At least one flight is required")
    try:
        total_baggages = int(total_baggages)
        nonfree_baggages = int(nonfree_baggages)
    except (TypeError, ValueError):
        raise ValueError("Invalid baggage numbers")
    if nonfree_baggages < 0 or total_baggages < 0 or nonfree_baggages > total_baggages:
        raise ValueError("Invalid baggage numbers")

    # ---------- flights ----------
    flight_rows = _rows(state, "flights")
    date_rows = _rows(state, "flight_dates")
    n_pax = len(passengers)
    segments = []
    total_price = 0
    for idx, f in enumerate(flights):
        if not isinstance(f, dict):
            raise ValueError("Invalid flight entry")
        flight_number = f.get("flight_number")
        date = f.get("date")
        if not flight_number or not date:
            raise ValueError("Each flight needs a flight_number and a date")
