def calculate(state, expression):
    """Calculate the result of a mathematical expression.

    Checks: the expression may only contain digits, the operators + - * /,
    parentheses, decimal points and spaces, and must be a valid expression.
    Logic: evaluate the expression and return the result rounded to 2 decimals.
    """
    if not isinstance(expression, str):
        raise ValueError("Invalid expression")

    allowed = set("0123456789+-*/(). ")
    if not expression.strip():
        raise ValueError("Invalid expression")
    if not all(char in allowed for char in expression):
        raise ValueError("Invalid characters in expression")

    try:
        result = eval(expression, {"__builtins__": {}}, {})
    except ZeroDivisionError:
        raise ValueError("Division by zero in expression")
    except Exception:
        raise ValueError("Invalid expression")

    if not isinstance(result, (int, float)) or isinstance(result, bool):
        raise ValueError("Invalid expression")

    return str(round(float(result), 2))

