def cancel_reservation(state, reservation_id):
    """Cancel the whole reservation."""
    if not reservation_id or not isinstance(reservation_id, str):
        raise ValueError("reservation_id must be a non-empty string")

    reservation = _find(state, "reservations", "reservation_id", reservation_id)

    if str(reservation.get("status", "")).lower() == "cancelled":
        raise ValueError("Reservation " + reservation_id + " is already cancelled")

    # Total amount paid for this reservation (to be refunded to original methods)
    refund_amount = 0
    for payment in _rows(state, "reservation_payments"):
        if payment.get("reservation_id") == reservation_id:
            try:
                refund_amount += payment.get("amount", 0) or 0
            except TypeError:
                pass

    reservation["status"] = "cancelled"

    return (
        "Reservation " + reservation_id + " has been cancelled. A refund of $"
        + str(refund_amount)
        + " will be returned to the original payment method(s) within 5 to 7 business days."
    )

