def get_flight_status(state, flight_number, date):
    """Get the status of a flight on a given date."""
    if not flight_number:
        raise ValueError("flight_number is required")
    if not date:
        raise ValueError("date is required")

    flight_dates = _rows(state, "flight_dates")
    record = None
    for row in flight_dates:
        if row.get("flight_number") == flight_number and row.get("date") == date:
            record = row
            break
    if record is None:
        raise ValueError(
            "Flight " + str(flight_number) + " not found on date " + str(date)
        )

    # Locate static flight information (origin/destination/scheduled times) if present.
    flight_info = None
    for row in _rows(state, "flights"):
        if row.get("flight_number") == flight_number or row.get("id") == flight_number:
            flight_info = row
            break

    status = record.get("status")
    result = {
        "flight_number": flight_number,
        "date": date,
        "status": status,
    }

    if flight_info is not None:
        result["origin"] = flight_info.get("origin")
        result["destination"] = flight_info.get("destination")
        result["scheduled_departure_time"] = flight_info.get("scheduled_departure_time")
        result["scheduled_arrival_time"] = flight_info.get("scheduled_arrival_time")
    else:
        result["origin"] = record.get("origin")
        result["destination"] = record.get("destination")

    if status == "available":
        result["available_seats"] = {
            "basic_economy": record.get("available_seats_basic_economy"),
            "economy": record.get("available_seats_economy"),
            "business": record.get("available_seats_business"),
        }
        result["prices"] = {
            "basic_economy": record.get("price_basic_economy"),
            "economy": record.get("price_economy"),
            "business": record.get("price_business"),
        }
    else:
        actual_departure = record.get("actual_departure_time")
        actual_arrival = record.get("actual_arrival_time")
        if actual_departure:
            result["actual_departure_time"] = actual_departure
        if actual_arrival:
            result["actual_arrival_time"] = actual_arrival

    return result

