def get_user_details(state, user_id):
    """Get the details of a user, including their reservations.

    Read-only lookup. Raises ValueError if the user does not exist.
    """
    if not user_id or not isinstance(user_id, str):
        raise ValueError("user_id must be a non-empty string")

    user = None
    for u in _rows(state, "users"):
        if u.get("user_id") == user_id or u.get("id") == user_id:
            user = u
            break
    if user is None:
        raise ValueError("User {} not found".format(user_id))

    details = dict(user)
    details["user_id"] = user_id

    # Payment methods belonging to this user
    payment_methods = []
    for p in _rows(state, "payment_methods"):
        if p.get("user_id") == user_id:
            payment_methods.append(dict(p))
    details["payment_methods"] = payment_methods

    # Reservations belonging to this user (ids plus a short summary)
    reservation_ids = []
    reservations = []
    for r in _rows(state, "reservations"):
        if r.get("user_id") != user_id:
            continue
        rid = r.get("reservation_id", r.get("id"))
        if rid is not None:
            reservation_ids.append(rid)
        summary = dict(r)
        if rid is not None:
            summary["reservation_id"] = rid
        reservations.append(summary)

    details["reservations"] = reservation_ids
    details["reservation_details"] = reservations

    return details

