# confidence=high  # note: Assumed the flights collection identifies each flight by a 'flight_number' key (falling back to 'id'
def search_direct_flight(state, origin, destination, date):
    """Search for direct flights between two cities on a specific date.

    Returns a list of flights that fly from `origin` to `destination` and are
    available (status == 'available') on the given date, together with the
    seat availability and prices for that date.
    """
    if not isinstance(origin, str) or not origin.strip():
        raise ValueError("origin must be a non-empty three letter airport code")
    if not isinstance(destination, str) or not destination.strip():
        raise ValueError("destination must be a non-empty three letter airport code")
    if not isinstance(date, str) or not date.strip():
        raise ValueError("date must be a non-empty string in the format 'YYYY-MM-DD'")

    origin = origin.strip().upper()
    destination = destination.strip().upper()
    date = date.strip()

    try:
        import datetime as _dt
        _dt.datetime.strptime(date, "%Y-%m-%d")
    except Exception:
        raise ValueError("date must be in the format 'YYYY-MM-DD', such as '2024-01-01'")

    flights = _rows(state, "flights")
    flight_dates = _rows(state, "flight_dates")

    # Map flight number -> flight record for the requested route
    matching = {}
    for flight in flights:
        f_origin = (flight.get("origin") or "").upper()
        f_dest = (flight.get("destination") or "").upper()
        if f_origin != origin or f_dest != destination:
            continue
        number = flight.get("flight_number") or flight.get("id")
        if number is None:
            continue
        matching[number] = flight

    results = []
    for fd in flight_dates:
        number = fd.get("flight_number")
        if number not in matching:
            continue
        if fd.get("date") != date:
            continue
        if fd.get("status") != "available":
            continue
        flight = matching[number]
        results.append({
            "flight_number": number,
            "origin": flight.get("origin"),
            "destination": flight.get("destination"),
            "scheduled_departure_time_est": flight.get("scheduled_departure_time"),
            "scheduled_arrival_time_est": flight.get("scheduled_arrival_time"),
            "date": date,
            "status": fd.get("status"),
            "available_seats": {
                "basic_economy": fd.get("available_seats_basic_economy"),
                "economy": fd.get("available_seats_economy"),
                "business": fd.get("available_seats_business"),
            },
            "prices": {
                "basic_economy": fd.get("price_basic_economy"),
                "economy": fd.get("price_economy"),
                "business": fd.get("price_business"),
            },
        })

    results.sort(key=lambda f: str(f.get("flight_number")))
    return results

