def search_onestop_flight(state, origin, destination, date):
    """Search for one-stop (single connection) flights between two cities on a date.

    Returns a list of itineraries; each itinerary is a list of two flight dicts
    (first leg, second leg). Read-only.
    """
    import datetime as _dt

    if not isinstance(origin, str) or len(origin) != 3:
        raise ValueError("Invalid origin airport code: {}".format(origin))
    if not isinstance(destination, str) or len(destination) != 3:
        raise ValueError("Invalid destination airport code: {}".format(destination))
    origin = origin.upper()
    destination = destination.upper()
    if origin == destination:
        raise ValueError("Origin and destination must be different")
    try:
        base_date = _dt.datetime.strptime(date, "%Y-%m-%d").date()
    except Exception:
        raise ValueError("Invalid date format, expected 'YYYY-MM-DD': {}".format(date))

    next_date = (base_date + _dt.timedelta(days=1)).strftime("%Y-%m-%d")

    def _flight_number(f):
        for key in ("flight_number", "id", "flight_id"):
            if f.get(key):
                return f.get(key)
        return None

    flights = _rows(state, "flights")
    flight_dates = _rows(state, "flight_dates")

    # index flight date records by (flight_number, date)
    date_index = {}
    for fd in flight_dates:
        date_index[(fd.get("flight_number"), fd.get("date"))] = fd

    def _detail(flight, fnum, day):
        fd = date_index.get((fnum, day))
        if fd is None or fd.get("status") != "available":
            return None
        return {
            "flight_number": fnum,
            "origin": flight.get("origin"),
            "destination": flight.get("destination"),
            "scheduled_departure_time": flight.get("scheduled_departure_time"),
            "scheduled_arrival_time": flight.get("scheduled_arrival_time"),
            "status": fd.get("status"),
            "date": day,
            "available_seats": {
                "basic_economy": fd.get("available_seats_basic_economy"),
                "economy": fd.get("available_seats_economy"),
                "business": fd.get("available_seats_business"),
            },
            "prices": {
                "basic_economy": fd.get("price_basic_economy"),
                "economy": fd.get("price_economy"),
                "business": fd.get("price_business"),
            },
        }

    results = []
    for first in flights:
        if first.get("origin") != origin:
            continue
        fnum1 = _flight_number(first)
        if fnum1 is None:
            continue
        leg1 = _detail(first, fnum1, date)
        if leg1 is None:
            continue
        for second in flights:
            if second.get("destination") != destination:
                continue
            if second.get("origin") != first.get("destination"):
                continue
            if second.get("destination") == first.get("origin"):
                continue
            fnum2 = _flight_number(second)
            if fnum2 is None or fnum2 == fnum1:
                continue
            arr = first.get("scheduled_arrival_time") or ""
            dep = second.get("scheduled_departure_time") or ""
            second_date = next_date if arr > dep else date
            leg2 = _detail(second, fnum2, second_date)
            if leg2 is None:
                continue
            results.append([dict(leg1), leg2])

    return results

# confidence=medium  # note: Assumed users are keyed by a 'user_id' field (as referenced by payment_methods/reservations) and tha
def send_certificate(state, user_id, amount):
    """Send a certificate (as a new travel certificate payment method) to a user."""
    # Validate the user exists (raises ValueError if absent)
    _find(state, "users", "user_id", user_id)

    # Validate the amount
    if isinstance(amount, bool) or not isinstance(amount, int):
        raise ValueError("Amount must be an integer")
    if amount <= 0:
        raise ValueError("Amount must be a positive integer")

    payments = _rows(state, "payment_methods")
    existing_ids = set()
    for p in payments:
        pid = p.get("id")
        if pid is not None:
            existing_ids.add(pid)

    # Deterministically generate a fresh certificate id
    number = 3221322 + len(payments)
    certificate_id = "certificate_" + str(number)
    while certificate_id in existing_ids:
        number += 1
        certificate_id = "certificate_" + str(number)

    payments.append(
        {
            "user_id": user_id,
            "source": "certificate",
            "brand": "",
            "last_four": "",
            "amount": amount,
            "id": certificate_id,
        }
    )

    _rows(state, "sent_certificates").append({"user_id": user_id, "amount": amount})

    return (
        "Certificate "
        + certificate_id
        + " added to user "
        + user_id
        + " with amount $"
        + str(amount)
        + "."
    )

# confidence=high  # note: Assumed a non-empty summary is a precondition and that a second transfer in the same session is an e
def transfer_to_human_agents(state, summary):
    if not isinstance(summary, str) or not summary.strip():
        raise ValueError("summary is required and must be a non-empty string")

    session = state.get("session")
    if not isinstance(session, dict):
        raise ValueError("session is not available")

    if session.get("transferred_to_human_agent"):
        raise ValueError("The user has already been transferred to a human agent")

    session["transferred_to_human_agent"] = True
    session["transfer_summary"] = summary.strip()

    return "Transfer successful"

# confidence=medium  # note: Assumed reservation records are keyed by 'reservation_id'. Charged $50 per newly added non-free bag;
def update_reservation_baggages(state, reservation_id, total_baggages, nonfree_baggages, payment_id):
    """Update the baggage information of a reservation."""
    reservation = _find(state, "reservations", "reservation_id", reservation_id)

    if reservation.get("status") == "cancelled":
        raise ValueError("Reservation is cancelled and cannot be updated")

    try:
        total_baggages = int(total_baggages)
        nonfree_baggages = int(nonfree_baggages)
    except (TypeError, ValueError):
        raise ValueError("Baggage counts must be integers")

    if total_baggages < 0 or nonfree_baggages < 0:
        raise ValueError("Baggage counts cannot be negative")
    if nonfree_baggages > total_baggages:
        raise ValueError("Non-free baggages cannot exceed total baggages")

    current_total = reservation.get("total_baggages", 0) or 0
    current_nonfree = reservation.get("nonfree_baggages", 0) or 0

    # Policy: the user can add but not remove checked bags.
    if total_baggages < current_total:
        raise ValueError("Checked bags can be added but not removed")

    total_price = 50 * max(0, nonfree_baggages - current_nonfree)

    user_id = reservation.get("user_id")
    payment = None
    for p in _rows(state, "payment_methods"):
        if p.get("id") == payment_id and p.get("user_id") == user_id:
            payment = p
            break
    if payment is None:
        raise ValueError("Payment method not found")

    source = payment.get("source")
    if source == "certificate":
        raise ValueError("Certificate cannot be used to update reservation")
    if source == "gift_card" and (payment.get("amount") or 0) < total_price:
        raise ValueError("Gift card balance is not enough")

    reservation["total_baggages"] = total_baggages
    reservation["nonfree_baggages"] = nonfree_baggages

    if source == "gift_card" and total_price > 0:
        payment["amount"] = (payment.get("amount") or 0) - total_price

    result = dict(reservation)
    result["reservation_id"] = reservation_id
    result["flights"] = sorted(
        [dict(f) for f in _rows(state, "reservation_flights")
         if f.get("reservation_id") == reservation_id],
        key=lambda f: f.get("segment_index", 0),
    )
    result["passengers"] = [
        dict(p) for p in _rows(state, "reservation_passengers")
        if p.get("reservation_id") == reservation_id
    ]
    result["payment_history"] = [
        dict(p) for p in _rows(state, "reservation_payments")
        if p.get("reservation_id") == reservation_id
    ]
    return result

# confidence=medium  # note: Assumed primary keys are stored as 'reservation_id'/'flight_number' (falling back to 'id') since the
def update_reservation_flights(state, reservation_id, cabin, flights, payment_id):
    """Update the flight information of a reservation."""

    def _norm_cabin(c):
        return str(c).strip().lower().replace(" ", "_")

    def _lookup(table, key_names, value):
        for row in _rows(state, table):
            for k in key_names:
                if row.get(k) == value:
                    return row
        return None

    cabin_key = _norm_cabin(cabin)
    if cabin_key not in ("basic_economy", "economy", "business"):
        raise ValueError(
            "Invalid cabin "
            + str(cabin)
            + ": must be one of basic_economy, economy, business"
        )

    # ---- reservation ----
    reservation = _lookup("reservations", ("reservation_id", "id"), reservation_id)
    if reservation is None:
        raise ValueError("Reservation " + str(reservation_id) + " not found")

    user_id = reservation.get("user_id")

    passengers = [
        p
        for p in _rows(state, "reservation_passengers")
        if p.get("reservation_id") == reservation_id
    ]
    num_passengers = len(passengers)
    if num_passengers == 0:
        raise ValueError(
            "Reservation " + str(reservation_id) + " has no passengers"
        )

    old_flights = sorted(
        [
            f
            for f in _rows(state, "reservation_flights")
            if f.get("reservation_id") == reservation_id
        ],
        key=lambda f: f.get("segment_index", 0),
    )

    if not isinstance(flights, list) or len(flights) == 0:
        raise ValueError("flights must be a non-empty array of flight segments")

    old_cabin = _norm_cabin(reservation.get("cabin", ""))

    # ---- build the new flight segments and compute the new total price ----
    new_flights = []
    total_price = 0
    for item in flights:
        if not isinstance(item, dict):
            raise ValueError("Each flight must be an object with flight_number and date")
        flight_number = item.get("flight_number")
        date = item.get("date")
        if not flight_number or not date:
            raise ValueError("Each flight must have a flight_number and a date")

        # kept segment: same flight number, same date, and cabin unchanged
        kept = None
        if cabin_key == old_cabin:
            for f in old_flights:
                if f.get("flight_number") == flight_number and f.get("date") == date:
                    kept = f
                    break
        if kept is not None:
            price = kept.get("price", 0)
            new_flights.append(
                {
                    "flight_number": flight_number,
                    "date": date,
                    "origin": kept.get("origin"),
                    "destination": kept.get("destination"),
                    "price": price,
                }
            )
            total_price += price * num_passengers
            continue

        flight_row = _lookup("flights", ("flight_number", "id"), flight_number)
        if flight_row is None:
            raise ValueError("Flight " + str(flight_number) + " not found")

        flight_date = None
        for fd in _rows(state, "flight_dates"):
            if fd.get("flight_number") == flight_number and fd.get("date") == date:
                flight_date = fd
                break
        if flight_date is None:
            raise ValueError(
                "Flight " + str(flight_number) + " not found on date " + str(date)
            )
        if flight_date.get("status") != "available":
            raise ValueError(
                "Flight " + str(flight_number) + " not available on date " + str(date)
            )
        seats = flight_date.get("available_seats_" + cabin_key, 0)
        if seats < num_passengers:
            raise ValueError("Not enough seats on flight " + str(flight_number))

        price = flight_date.get("price_" + cabin_key, 0)
        new_flights.append(
            {
                "flight_number": flight_number,
                "date": date,
                "origin": flight_row.get("origin"),
                "destination": flight_row.get("destination"),
                "price": price,
            }
        )
        total_price += price * num_passengers

    total_price -= sum(f.get("price", 0) for f in old_flights) * num_passengers

    # ---- payment ----
    payment_method = None
    for pm in _rows(state, "payment_methods"):
        if pm.get("id") == payment_id and pm.get("user_id") == user_id:
            payment_method = pm
            break
    if payment_method is None:
        raise ValueError("Payment method " + str(payment_id) + " not found")

    source = payment_method.get("source")
    if source == "certificate":
        raise ValueError("Certificate cannot be used to update reservation")
    if source == "gift_card" and payment_method.get("amount", 0) < total_price:
        raise ValueError("Gift card balance is not enough")

    if source == "gift_card":
        payment_method["amount"] = payment_method.get("amount", 0) - total_price

    # ---- writes ----
    rows = _rows(state, "reservation_flights")
    for f in old_flights:
        rows.remove(f)
    for idx, f in enumerate(new_flights):
        rows.append(
            {
                "reservation_id": reservation_id,
                "flight_number": f["flight_number"],
                "date": f["date"],
                "origin": f["origin"],
                "destination": f["destination"],
                "price": f["price"],
                "segment_index": idx,
            }
        )

    reservation["cabin"] = cabin_key

    _rows(state, "reservation_payments").append(
        {
            "reservation_id": reservation_id,
            "payment_id": payment_id,
            "amount": total_price,
        }
    )

    payment_history = [
        {
            "payment_id": p.get("payment_id"),
            "amount": p.get("amount"),
        }
        for p in _rows(state, "reservation_payments")
        if p.get("reservation_id") == reservation_id
    ]

    return {
        "reservation_id": reservation_id,
        "user_id": user_id,
        "origin": reservation.get("origin"),
        "destination": reservation.get("destination"),
        "flight_type": reservation.get("flight_type"),
        "cabin": reservation.get("cabin"),
        "flights": [
            {
                "flight_number": f["flight_number"],
                "date": f["date"],
                "origin": f["origin"],
                "destination": f["destination"],
                "price": f["price"],
            }
            for f in new_flights
        ],
        "passengers": [
            {
                "first_name": p.get("first_name"),
                "last_name": p.get("last_name"),
                "date_of_birth": p.get("date_of_birth"),
            }
            for p in passengers
        ],
        "payment_history": payment_history,
        "created_at": reservation.get("created_at"),
        "total_baggages": reservation.get("total_baggages"),
        "nonfree_baggages": reservation.get("nonfree_baggages"),
        "insurance": reservation.get("insurance"),
        "status": reservation.get("status"),
    }

# confidence=medium  # note: Assumed reservations rows are keyed by 'reservation_id' (falling back to 'id') since the schema omit
def update_reservation_passengers(state, reservation_id, passengers):
    """Update the passenger information of a reservation.

    Checks:
      - the reservation must exist
      - `passengers` must be a non-empty list of objects with first_name,
        last_name and date_of_birth
      - the number of passengers cannot be changed
    Logic:
      - overwrite the stored passenger records with the supplied ones
      - return the updated reservation
    """
    # ---- locate the reservation -------------------------------------------
    reservation = None
    try:
        reservation = _find(state, "reservations", "reservation_id", reservation_id)
    except Exception:
        reservation = None
    if reservation is None:
        for row in _rows(state, "reservations"):
            if row.get("reservation_id") == reservation_id or row.get("id") == reservation_id:
                reservation = row
                break
    if reservation is None:
        raise ValueError("Reservation not found")

    # ---- validate the incoming passenger list ------------------------------
    if not isinstance(passengers, list) or len(passengers) == 0:
        raise ValueError("passengers must be a non-empty list")

    cleaned = []
    for p in passengers:
        if not isinstance(p, dict):
            raise ValueError("Each passenger must be an object with first_name, last_name and date_of_birth")
        first_name = p.get("first_name")
        last_name = p.get("last_name")
        date_of_birth = p.get("date_of_birth")
        if not first_name or not last_name or not date_of_birth:
            raise ValueError("Each passenger must have first_name, last_name and date_of_birth")
        cleaned.append(
            {
                "first_name": first_name,
                "last_name": last_name,
                "date_of_birth": date_of_birth,
            }
        )

    if len(cleaned) > 5:
        raise ValueError("Each reservation can have at most five passengers")

    existing = [
        row
        for row in _rows(state, "reservation_passengers")
        if row.get("reservation_id") == reservation_id
    ]
    if len(existing) != len(cleaned):
        raise ValueError(
            "The number of passengers cannot be changed: reservation has "
            + str(len(existing))
            + " passenger(s)"
        )

    # ---- write -------------------------------------------------------------
    for old, new in zip(existing, cleaned):
        old["first_name"] = new["first_name"]
        old["last_name"] = new["last_name"]
        old["date_of_birth"] = new["date_of_birth"]

    # ---- build the response ------------------------------------------------
    flights = [
        {
            "flight_number": f.get("flight_number"),
            "date": f.get("date"),
            "origin": f.get("origin"),
            "destination": f.get("destination"),
            "price": f.get("price"),
            "segment_index": f.get("segment_index"),
        }
        for f in _rows(state, "reservation_flights")
        if f.get("reservation_id") == reservation_id
    ]
    flights.sort(key=lambda f: f.get("segment_index") or 0)

    payments = [
        {"payment_id": pay.get("payment_id"), "amount": pay.get("amount")}
        for pay in _rows(state, "reservation_payments")
        if pay.get("reservation_id") == reservation_id
    ]

    result = dict(reservation)
    result["reservation_id"] = reservation_id
    result["flights"] = flights
    result["passengers"] = cleaned
    result["payment_history"] = payments
    return result

# ---- derived state: recomputed after every call, like a database trigger
def derive(state):
    from datetime import datetime

    # ---------- helpers ----------
    def _cabin(c):
        return c.strip().lower().replace('-', '_').replace(' ', '_') if isinstance(c, str) else ''

    def _low(v):
        return v.strip().lower() if isinstance(v, str) else v

    def _uid(u):
        for k in ('user_id', 'id', 'uid'):
            if u.get(k):
                return u.get(k)
        return u.get('email')

    def _rid(r):
        for k in ('reservation_id', 'id', 'rid'):
            if r.get(k):
                return r.get(k)
        return None

    def _fnum(f):
        for k in ('flight_number', 'id', 'number'):
            if f.get(k):
                return f.get(k)
        return None

    def _dt(v):
        if not isinstance(v, str) or not v.strip():
            return None
        t = v.strip().replace('T', ' ')
        for fmt in ('%Y-%m-%d %H:%M:%S', '%Y-%m-%d %H:%M', '%Y-%m-%d'):
            try:
                return datetime.strptime(t, fmt)
            except Exception:
                pass
        return None

    def _num(v):
        try:
            return float(v)
        except Exception:
            return 0.0

    FREE = {
        'regular': {'basic_economy': 0, 'economy': 1, 'business': 2},
        'silver': {'basic_economy': 1, 'economy': 2, 'business': 3},
        'gold': {'basic_economy': 2, 'economy': 3, 'business': 4},
    }
    DEPARTED_STATUS = ('flying', 'landed', 'flown', 'completed')

    session = state.setdefault('session', {})
    now = _dt(session.get('current_time')) or _now(state)

    users = state.get('users') or []
    payment_methods = state.get('payment_methods') or []
    reservations = state.get('reservations') or []
    res_flights = state.get('reservation_flights') or []
    res_pax = state.get('reservation_passengers') or []
    res_pay = state.get('reservation_payments') or []
    flights = state.get('flights') or []
    flight_dates = state.get('flight_dates') or []
    certs = state.get('sent_certificates') or []

    # ---------- indexes ----------
    users_by_id = {}
    for u in users:
        if isinstance(u, dict):
            users_by_id[_uid(u)] = u

    pm_by_id = {}
    pm_by_user = {}
    for p in payment_methods:
        if not isinstance(p, dict):
            continue
        pm_by_id[p.get('id')] = p
        pm_by_user.setdefault(p.get('user_id'), []).append(p)

    fd_by_key = {}
    fd_by_number = {}
    for fd in flight_dates:
        if not isinstance(fd, dict):
            continue
        fd_by_key[(fd.get('flight_number'), fd.get('date'))] = fd
        fd_by_number.setdefault(fd.get('flight_number'), []).append(fd)

    segs_by_res = {}
    for rf in res_flights:
        if isinstance(rf, dict):
            segs_by_res.setdefault(rf.get('reservation_id'), []).append(rf)
    for k in segs_by_res:
        segs_by_res[k].sort(key=lambda x: (x.get('segment_index') if isinstance(x.get('segment_index'), int) else 0))

    pax_by_res = {}
    for p in res_pax:
        if isinstance(p, dict):
            pax_by_res.setdefault(p.get('reservation_id'), []).append(p)

    pay_by_res = {}
    for p in res_pay:
        if isinstance(p, dict):
            pay_by_res.setdefault(p.get('reservation_id'), []).append(p)

    # ---------- flight_dates observables ----------
    for fd in flight_dates:
        if not isinstance(fd, dict):
            continue
        st = _low(fd.get('status')) or ''
        d = _dt(fd.get('date'))
        departed = st in DEPARTED_STATUS
        if not departed and d is not None and d.date() < now.date():
            departed = True
        fd['is_bookable'] = (st == 'available') and not departed
        fd['is_cancelled'] = (st == 'cancelled')
        fd['is_delayed'] = (st == 'delayed')
        fd['has_departed'] = bool(departed)
        fd['seats_total_available'] = int(_num(fd.get('available_seats_basic_economy'))
                                          + _num(fd.get('available_seats_economy'))
                                          + _num(fd.get('available_seats_business')))
        fd['seats_nonnegative'] = all(_num(fd.get(k)) >= 0 for k in (
            'available_seats_basic_economy', 'available_seats_economy', 'available_seats_business'))

    # ---------- flights observables ----------
    for f in flights:
        if not isinstance(f, dict):
            continue
        n = _fnum(f)
        dates = fd_by_number.get(n, []) if n else []
        f['bookable_dates'] = sorted([fd.get('date') for fd in dates if fd.get('is_bookable') and fd.get('date')])
        f['scheduled_date_count'] = len(dates)

    # ---------- reservation observables ----------
    for r in reservations:
        if not isinstance(r, dict):
            continue
        rid = _rid(r)
        user = users_by_id.get(r.get('user_id')) or {}
        membership = _low(user.get('membership')) or 'regular'
        cabin = _cabin(r.get('cabin'))
        segs = segs_by_res.get(rid, [])
        pax = pax_by_res.get(rid, [])
        pays = pay_by_res.get(rid, [])
        n_pax = len(pax)

        price_pp = sum(_num(s.get('price')) for s in segs)
        per_pax_free = FREE.get(membership, FREE['regular']).get(cabin, 0)
        free_allow = per_pax_free * n_pax
        total_bags = int(_num(r.get('total_baggages')))
        nonfree_stored = int(_num(r.get('nonfree_baggages')))

        r['passenger_count'] = n_pax
        r['segment_count'] = len(segs)
        r['flight_price_per_passenger'] = price_pp
        r['flight_price_total'] = price_pp * n_pax
        r['free_baggage_allowance'] = free_allow
        r['expected_nonfree_baggages'] = max(0, total_bags - free_allow)
        r['baggage_fee'] = 50.0 * nonfree_stored
        r['insurance_total'] = 30.0 * n_pax if _low(r.get('insurance')) in ('yes', 'true', '1') else 0.0
        r['computed_total_cost'] = r['flight_price_total'] + r['baggage_fee'] + r['insurance_total']
        r['payments_total'] = sum(_num(p.get('amount')) for p in pays)
        r['payment_balanced'] = abs(r['payments_total'] - r['computed_total_cost']) < 0.01

        # payment method legality
        srcs = []
        pm_ok = True
        for p in pays:
            pm = pm_by_id.get(p.get('payment_id'))
            if pm is None:
                pm_ok = False
                continue
            if pm.get('user_id') != r.get('user_id'):
                pm_ok = False
            srcs.append(_low(pm.get('source')) or '')
        n_cc = sum(1 for s in srcs if 'credit' in str(s))
        n_gift = sum(1 for s in srcs if 'gift' in str(s))
        n_cert = sum(1 for s in srcs if 'certificate' in str(s))
        r['payment_sources'] = srcs
        r['payment_methods_valid'] = bool(pm_ok and n_cc <= 1 and n_cert <= 1 and n_gift <= 3)

        # itinerary shape
        connected = True
        for i in range(len(segs) - 1):
            if _low(segs[i].get('destination')) != _low(segs[i + 1].get('origin')):
                connected = False
        if segs:
            first_o = _low(segs[0].get('origin'))
            last_d = _low(segs[-1].get('destination'))
            computed_type = 'round_trip' if first_o == last_d else 'one_way'
            if computed_type == 'round_trip':
                endpoints_ok = (first_o == _low(r.get('origin')))
            else:
                endpoints_ok = (first_o == _low(r.get('origin')) and last_d == _low(r.get('destination')))
        else:
            computed_type = None
            endpoints_ok = False
        r['computed_flight_type'] = computed_type
        r['itinerary_connected'] = bool(connected)
        r['itinerary_endpoints_ok'] = bool(endpoints_ok)
        r['flight_type_matches_itinerary'] = bool(
            computed_type is not None
            and _cabin(r.get('flight_type')) == computed_type
        )

        # flown / disruption state
        any_flown = False
        all_flown = bool(segs)
        any_cancelled = False
        any_delayed = False
        for s in segs:
            fd = fd_by_key.get((s.get('flight_number'), s.get('date')))
            if fd is not None:
                dep = bool(fd.get('has_departed'))
                any_cancelled = any_cancelled or bool(fd.get('is_cancelled'))
                any_delayed = any_delayed or bool(fd.get('is_delayed'))
            else:
                d = _dt(s.get('date'))
                dep = bool(d is not None and d.date() < now.date())
            any_flown = any_flown or dep
            all_flown = all_flown and dep
        r['has_flown_segment'] = bool(any_flown)
        r['all_segments_flown'] = bool(all_flown)
        r['has_airline_cancelled_flight'] = bool(any_cancelled)
        r['has_delayed_flight'] = bool(any_delayed)

        created = _dt(r.get('created_at'))
        r['created_within_24h'] = bool(created is not None and 0 <= (now - created).total_seconds() <= 86400)

        r['is_active'] = _low(r.get('status')) not in ('cancelled', 'canceled')
        r['cancellation_permitted'] = bool(
            not r['has_flown_segment'] and (
                r['created_within_24h']
                or r['has_airline_cancelled_flight']
                or cabin == 'business'
                or _low(r.get('insurance')) in ('yes', 'true', '1')
            )
        )
        r['cancellation_needs_insurance_reason'] = bool(
            r['cancellation_permitted']
            and not r['created_within_24h']
            and not r['has_airline_cancelled_flight']
            and cabin != 'business'
        )
        r['flight_change_allowed'] = bool(r['is_active'] and not r['has_flown_segment'] and cabin != 'basic_economy')
        r['cabin_change_allowed'] = bool(r['is_active'] and not r['has_flown_segment'])
        r['compensation_eligible'] = bool(
            membership in ('silver', 'gold')
            or _low(r.get('insurance')) in ('yes', 'true', '1')
            or cabin == 'business'
        )
        r['cancelled_flight_certificate_amount'] = 100 * n_pax if r['compensation_eligible'] else 0
        r['delayed_flight_certificate_amount'] = 50 * n_pax if r['compensation_eligible'] else 0

    # ---------- user observables ----------
    cert_total_by_user = {}
    for c in certs:
        if isinstance(c, dict):
            cert_total_by_user[c.get('user_id')] = cert_total_by_user.get(c.get('user_id'), 0.0) + _num(c.get('amount'))

    for u in users:
        if not isinstance(u, dict):
            continue
        uid = _uid(u)
        mine = [r for r in reservations if isinstance(r, dict) and r.get('user_id') == uid]
        u['reservation_ids'] = sorted([x for x in (_rid(r) for r in mine) if x])
        u['reservation_count'] = len(mine)
        u['active_reservation_count'] = sum(1 for r in mine if r.get('is_active'))
        u['payment_method_ids'] = sorted([p.get('id') for p in pm_by_user.get(uid, []) if p.get('id')])
        u['certificates_total_sent'] = cert_total_by_user.get(uid, 0.0)
        m = _low(u.get('membership')) or 'regular'
        u['free_checked_bags_by_cabin'] = dict(FREE.get(m, FREE['regular']))

    # ---------- session observables ----------
    session['is_authenticated'] = bool(session.get('authenticated_user_id') in users_by_id
                                       and session.get('authenticated_user_id'))
    session['transfer_completed'] = bool(session.get('transferred_to_human_agent')
                                         and isinstance(session.get('transfer_summary'), str)
                                         and session.get('transfer_summary').strip())
    return state

# The session is bound to an authenticated user id that actually exists in the user table.
def user_authenticated(state):
    derive(state)
    return bool((state.get('session') or {}).get('is_authenticated'))

# Every non-cancelled reservation's recorded payments exactly equal flights + baggage fees + insurance.
def all_active_reservations_paid_correctly(state):
    derive(state)
    for r in (state.get('reservations') or []):
        if not isinstance(r, dict):
            continue
        if not r.get('is_active'):
            continue
        if not r.get('payment_balanced'):
            return False
    return True

# Charged (non-free) bags on every reservation match the membership/cabin free allowance for its passengers.
def all_reservations_baggage_consistent(state):
    derive(state)
    for r in (state.get('reservations') or []):
        if not isinstance(r, dict):
            continue
        try:
            total = int(float(r.get('total_baggages') or 0))
            nonfree = int(float(r.get('nonfree_baggages') or 0))
        except Exception:
            return False
        if total < 0 or nonfree < 0 or nonfree > total:
            return False
        if nonfree != int(r.get('expected_nonfree_baggages') or 0):
            return False
    return True

# Every active reservation carries between one and five passengers.
def all_reservations_within_passenger_limit(state):
    derive(state)
    for r in (state.get('reservations') or []):
        if isinstance(r, dict) and r.get('is_active'):
            n = int(r.get('passenger_count') or 0)
            if n < 1 or n > 5:
                return False
    return True

# Every reservation pays only with methods in the owning user's profile and respects 1 credit card / 1 certificate / 3 gift cards.
def all_reservation_payments_valid(state):
    derive(state)
    for r in (state.get('reservations') or []):
        if isinstance(r, dict) and not r.get('payment_methods_valid'):
            return False
    return True

# Each active reservation's segments connect end-to-end and start/end at the reservation's declared origin/destination for its trip type.
def all_itineraries_well_formed(state):
    derive(state)
    for r in (state.get('reservations') or []):
        if not isinstance(r, dict) or not r.get('is_active'):
            continue
        if int(r.get('segment_count') or 0) < 1:
            return False
        if not (r.get('itinerary_connected') and r.get('itinerary_endpoints_ok')):
            return False
    return True

# Every cancelled reservation met a policy cancellation ground (24h window, airline cancellation, business cabin, or insurance) and had no flown segment.
def all_cancellations_authorized(state):
    derive(state)
    for r in (state.get('reservations') or []):
        if not isinstance(r, dict):
            continue
        if r.get('is_active'):
            continue
        if r.get('has_flown_segment'):
            return False
        if not r.get('cancellation_permitted'):
            return False
    return True

# No flight date has negative seat inventory in any cabin, i.e. nothing was booked beyond availability.
def no_seats_oversold(state):
    derive(state)
    for fd in (state.get('flight_dates') or []):
        if isinstance(fd, dict) and not fd.get('seats_nonnegative'):
            return False
    return True

# Every compensation certificate went to an eligible user (silver/gold, insured, or business) for $100 or $50 times that reservation's passenger count.
def all_certificates_justified(state):
    derive(state)
    res = [r for r in (state.get('reservations') or []) if isinstance(r, dict)]
    for c in (state.get('sent_certificates') or []):
        if not isinstance(c, dict):
            return False
        uid = c.get('user_id')
        try:
            amt = float(c.get('amount') or 0)
        except Exception:
            return False
        if amt <= 0:
            return False
        allowed = set()
        for r in res:
            if r.get('user_id') != uid:
                continue
            if r.get('cancelled_flight_certificate_amount'):
                allowed.add(float(r['cancelled_flight_certificate_amount']))
            if r.get('delayed_flight_certificate_amount'):
                allowed.add(float(r['delayed_flight_certificate_amount']))
        if amt not in allowed:
            return False
    return True

# The conversation was handed to a human agent with a non-empty transfer summary recorded.
def transfer_completed_properly(state):
    derive(state)
    return bool((state.get('session') or {}).get('transfer_completed'))

# No reservation with an already-flown segment is still marked as changeable in flights or cabin.
def no_flown_reservation_left_modifiable(state):
    derive(state)
    for r in (state.get('reservations') or []):
        if not isinstance(r, dict):
            continue
        if r.get('has_flown_segment') and (r.get('flight_change_allowed') or r.get('cabin_change_allowed')):
            return False
    return True

